final class StudentAchievementLifecycleController extends Controller{
 use ResponseTrait;public function __construct(private ?AuthorizationService $auth=null,private ?CanonicalStudentAchievementDraftService $drafts=null,private ?LocalEvidenceStorageService $storage=null,private ?StudentEvidenceClamAvScanner $scanner=null,private ?StudentEvidencePaddleOcrService $ocr=null,private ?BaseConnection $database=null){}
