 public function options():mixed{return $this->respond(null,204);} public function create():mixed{return $this->run(fn($a)=>$this->service()->create($a['profile']['id']),201);} public function show(string $id):mixed{return $this->run(fn($a)=>$this->service()->read($a['profile']['id'],$id),200,false);}
