 public function upload(string $id):mixed{return $this->run(function($a)use($id){$view=$this->service()->read($a['profile']['id'],$id);if(!in_array($view['version']['submission_state'],['draft','revision_requested'],true))throw new \RuntimeException('STUDENT_ACHIEVEMENT_VERSION_NOT_EDITABLE');$f=$this->request->getFile('file');if(!$f||!$f->isValid())throw new \RuntimeException('FILE_REQUIRED');$s=$this->storage??=new LocalEvidenceStorageService();$v=(new StudentAchievementEvidenceUploadPolicy($s))->validate($f->getTempName(),$f->getClientName());if(!($v['success']??false))throw new \RuntimeException($v['error_code']??'STUDENT_EVIDENCE_TYPE_NOT_ALLOWED');$stored=$s->storeFile($f->getTempName(),'student',$a['profile']['id'],$id,$v['extension'],true);$eid=$this->uuid();$this->database()->table('achievement_evidence')->insert(['id'=>$eid,'storage_path'=>$stored['storage_path'],'original_filename'=>$f->getClientName(),'mime_type'=>$v['detected_mime'],'detected_mime_type'=>$v['detected_mime'],'byte_size'=>$stored['byte_size'],'sha256'=>$stored['sha256'],'uploaded_by'=>$a['profile']['id'],'security_status'=>'pending','malware_scanner'=>'clamav_pending','status'=>'active']);$this->database()->table('achievement_version_evidence')->insert(['record_version_id'=>$view['version']['id'],'evidence_id'=>$eid,'association_type'=>'student_supporting_evidence','is_primary'=>1,'attached_by'=>$a['profile']['id']]);return ['evidence_id'=>$eid,'security_status'=>'pending'];},201);}
