 public function remove(string $id,string $evidence):mixed{return $this->run(fn($a)=>$this->service()->detachEvidence($a['profile']['id'],$id,$evidence));}
 public function scan(string $id,string $evidence):mixed{return $this->run(function($a)use($id,$evidence){$v=$this->service()->read($a['profile']['id'],$id);$e=null;foreach($v['evidence'] as $row)if($row['id']===$evidence)$e=$row;if(!$e)throw new \RuntimeException('EVIDENCE_NOT_FOUND');$row=$this->database()->table('achievement_evidence')->where('id',$evidence)->get()->getRowArray();$path=($this->storage??=new LocalEvidenceStorageService())->resolveAbsolutePath($row['storage_path']);$r=($this->scanner??=new StudentEvidenceClamAvScanner())->scan((string)$path);$response=['scan'=>$r];if($r['status']==='clean'){$this->database()->table('achievement_evidence')->where('id',$evidence)->update(['security_status'=>'clean','malware_scanner'=>'clamav_1_5_4','security_validated_at'=>date('Y-m-d H:i:s.u')]);try{$response['ocr']=($this->ocr??=new StudentEvidencePaddleOcrService())->extract((string)$path,(string)$row['detected_mime_type']);}catch(Throwable $x){$response['ocr_error']='OCR assistance was unavailable. You can continue with manual entry.';}}elseif($r['status']==='infected')$this->database()->table('achievement_evidence')->where('id',$evidence)->update(['security_status'=>'rejected','status'=>'rejected','malware_scanner'=>'clamav_1_5_4','security_validated_at'=>date('Y-m-d H:i:s.u')]);return $response;});}
